// ---------------------------------------------------------------------------

// --- Phía extension: `loadExtensionFromFactory` (loader.ts:464) nhận factory
// --- inline nên closure giữ được disposer. Không cần file tạm.
const extension = await loadExtensionFromFactory(
	async (api) => {
